-- Clés de traduction STABLES. Avant : la clé était le texte français de la page (L.T("Lois", "Laws")) : retoucher une phrase faisait retomber toutes ses traductions sur l'anglais,
-- sans erreur ni alerte. Après : la clé est un identifiant écrit dans la page (L.T("accueil-accroche", "Lois", "Laws")) ; la table garde en plus le FRANÇAIS TRADUIT (source_fr) pour
-- repérer une traduction périmée (phrase de la page changée depuis). Cette migration renomme les lignes existantes : ancienne clé (texte français) -> nouvelle clé, copiées en
-- plusieurs exemplaires quand un même français porte plusieurs clés (même phrase, anglais différent selon la page). Les lignes sans correspondance sont conservées telles quelles
-- (elles apparaissent dans l'administration avec leur source). Sauvegarde préalable recommandée : pg_dump -t traductions.
BEGIN;

ALTER TABLE traductions ADD COLUMN IF NOT EXISTS source_fr text;
-- Ancien système : la clé EST le texte français traduit.
UPDATE traductions SET source_fr = cle WHERE source_fr IS NULL;

CREATE TEMP TABLE cle_map (ancienne text NOT NULL, nouvelle text NOT NULL) ON COMMIT DROP;

-- Les anciennes lignes sont d'abord MISES DE CÔTÉ sous un préfixe : une nouvelle clé peut être identique à un ancien texte français (la clé « groupe » est à la fois l'ancien texte
-- « groupe » et la nouvelle clé de « Groupe ») ; sans cette précaution la copie écraserait ou ignorerait la mauvaise ligne.
UPDATE traductions SET cle = 'ancienne:' || cle WHERE cle NOT LIKE 'ancienne:%';

-- Copie sous la nouvelle clé (sans écraser une ligne déjà présente) ...
SELECT t.langue, m.nouvelle, t.texte, t.source_fr, t.maj
  FROM traductions t JOIN cle_map m ON 'ancienne:' || m.ancienne = t.cle
ON CONFLICT (langue, cle) DO NOTHING;

-- ... les lignes sans correspondance (orphelines : texte retiré du code) reprennent leur ancienne clé si elle est libre ...
SELECT t.langue, substring(t.cle FROM 10), t.texte, t.source_fr, t.maj
  FROM traductions t
 WHERE t.cle LIKE 'ancienne:%'
   AND NOT EXISTS (SELECT 1 FROM cle_map m WHERE 'ancienne:' || m.ancienne = t.cle)
ON CONFLICT (langue, cle) DO NOTHING;

-- ... puis suppression de toutes les lignes mises de côté.
DELETE FROM traductions WHERE cle LIKE 'ancienne:%';

-- Ligne orpheline : l'ancienne accroche de l'accueil (retirée du code) ; sa clé (le texte français entier) ne correspond plus à rien.
DELETE FROM traductions WHERE cle LIKE 'Chaque point est un élu.%';

COMMIT;
